 PARTITIONED BY (
 lyear string )
 ROW FORMAT SERDE
 &amp;apos;org.apache.hadoop.hive.ql.io.parquet.serde.ParquetHiveSerDe&amp;apos;
 STORED AS INPUTFORMAT
 &amp;apos;org.apache.hadoop.hive.ql.io.parquet.MapredParquetInputFormat&amp;apos;
