	} else if (value instanceof List) {




		List listValue = new ArrayList&lt;Object&gt;();




		for (Object v : (List)value) {




			if (v instanceof LongString) {




				v = this.convertLongString((LongString) v, charset);




			}




			listValue.add(v);




		}




		value = listValue;




	}




	target.setHeader(entry.getKey(), value);




}

