eg:
if (stepDate.after(latest)) {
    latest = stepDate;
    stepExecution = candidate;
    // hack when stepExecution endTimes are not granular enough.
} else if (stepDate.equals(latest) &amp;&amp; candidate.getId() &gt; stepExecution.getId()) {
    latest = stepDate;
    stepExecution = candidate;
}

