        inverseJoinColumns=@JoinColumn(name="entity_ancestor_id")




    )




    public Set&lt;TreeEntity&gt; getAncestors() {




        return ancestors;




    }






and I have a method on my repository:






    @Query("select " +




            "    distinct entity.ancestors " +




            "from " +




            "    example.data.TreeEntity entity " +




            "where " +




            "    entity.id = :entityId")




